from django.db import connections
from django.views.decorators.csrf import csrf_exempt
from django.views.generic import View
from django.utils.cache import patch_vary_headers

from rest_framework import exceptions, status
from rest_framework.request import Request
from rest_framework.response import Response
from rest_framework.settings import api_settings
from rest_framework.utils import formatting


def get_view_name(view):
    """
    Retorna um nome textual para representar a view.
    Esse nome é usado na API navegável e nas respostas de OPTIONS.
    """
    name = getattr(view, 'name', None)
    if name:
        return name
    return formatting.camelcase_to_spaces(view.__class__.__name__)


def set_rollback():
    for db in connections.all():
        if db.settings_dict['ATOMIC_REQUESTS'] and db.in_atomic_block:
            db.set_rollback(True)


class APIView(View):
    # Configurações padrão para a API
    renderer_classes = api_settings.DEFAULT_RENDERER_CLASSES
    parser_classes = api_settings.DEFAULT_PARSER_CLASSES
    authentication_classes = api_settings.DEFAULT_AUTHENTICATION_CLASSES
    throttle_classes = api_settings.DEFAULT_THROTTLE_CLASSES
    permission_classes = api_settings.DEFAULT_PERMISSION_CLASSES
    content_negotiation_class = api_settings.DEFAULT_CONTENT_NEGOTIATION_CLASS
    metadata_class = api_settings.DEFAULT_METADATA_CLASS

    @classmethod
    def as_view(cls, **initkwargs):
        """
        Cria a função de visualização a partir da classe, tornando-a CSRF isenta.
        """
        view = super().as_view(**initkwargs)
        view.cls = cls
        view.initkwargs = initkwargs
        return csrf_exempt(view)

    def get_permissions(self):
        """
        Instancia e retorna a lista de permissões que esta view requer.
        """
        return [permission() for permission in self.permission_classes]

    def check_permissions(self, request):
        """
        Verifica se a requisição deve ser permitida.
        Levanta uma exceção apropriada se a requisição não for permitida.
        """
        for permission in self.get_permissions():
            if not permission.has_permission(request, self):
                raise exceptions.PermissionDenied()

    def initialize_request(self, request, *args, **kwargs):
        """
        Inicializa o objeto de requisição.
        """
        parser_context = {
            'view': self,
            'args': args,
            'kwargs': kwargs
        }
        return Request(
            request,
            parsers=[parser() for parser in self.parser_classes],
            authenticators=[auth() for auth in self.authentication_classes],
            negotiator=self.content_negotiation_class(),
            parser_context=parser_context
        )

    def initial(self, request, *args, **kwargs):
        """
        Executa operações iniciais, como verificação de permissões.
        """
        self.check_permissions(request)

    def dispatch(self, request, *args, **kwargs):
        """
        Controla o ciclo de vida completo de uma requisição.
        """
        self.args = args
        self.kwargs = kwargs
        request = self.initialize_request(request, *args, **kwargs)
        self.request = request
        self.headers = self.default_response_headers

        try:
            self.initial(request, *args, **kwargs)

            # Obter o método de tratamento apropriado
            if request.method.lower() in self.http_method_names:
                handler = getattr(self, request.method.lower(), self.http_method_not_allowed)
            else:
                handler = self.http_method_not_allowed

            response = handler(request, *args, **kwargs)

        except Exception as exc:
            response = self.handle_exception(exc)

        return self.finalize_response(request, response, *args, **kwargs)

    def finalize_response(self, request, response, *args, **kwargs):
        """
        Retorna o objeto de resposta final.
        """
        if isinstance(response, Response):
            response.accepted_renderer = request.accepted_renderer
            response.accepted_media_type = request.accepted_media_type
            response.renderer_context = {
                'view': self,
                'args': args,
                'kwargs': kwargs,
                'request': request
            }

        vary_headers = self.headers.pop('Vary', None)
        if vary_headers is not None:
            patch_vary_headers(response, vary_headers.split(','))

        for key, value in self.headers.items():
            response[key] = value

        return response

    def handle_exception(self, exc):
        """
        Lida com exceções e retorna uma resposta apropriada.
        """
        set_rollback()
        
        if isinstance(exc, (exceptions.NotAuthenticated, exceptions.AuthenticationFailed)):
            exc.auth_header = self.get_authenticate_header(self.request)
            exc.status_code = status.HTTP_403_FORBIDDEN

        response = exceptions.exception_handler(exc, {'view': self, 'request': self.request})
        if response is None:
            self.raise_uncaught_exception(exc)

        response.exception = True
        return response

    def options(self, request, *args, **kwargs):
        """
        Lida com requisições HTTP 'OPTIONS'.
        """
        data = self.metadata_class().determine_metadata(request, self)
        return Response(data, status=status.HTTP_200_OK)
